    "🧬 Xenobots — живые роботы из клеток лягушки — запрограммированы алгоритмами эволюции. Они могут самовоспроизводиться, собирая клетки в новые организмы.",
    "⚛️ Левитация диамагнетиков: вода, пластик, живые организмы отталкиваются от сильного магнита. Андре Гейм левитировал лягушку в 16-тесловом поле.",
    "🌌 Поляриметрия чёрных дыр: Event Horizon Telescope измерил поляризацию света вокруг M87* — закрученные магнитные поля, питающие джет длиной 5000 световых лет.",
    "🔬 Атомная литография: сфокусированный ионный пучок вырезает структуры размером 5 нм. Используется для создания прототипов микросхем и квантовых устройств.",
    "🧬 Органоиды — мини-органы из стволовых клеток — воспроизводят структуру мозга, печени, кишечника. Мозговые органоиды развивают нейронную активность за месяцы.",
    "⚛️ Сверхпроводимость при комнатной температуре достигнута в 2020 году — но при давлении 2.6 миллиона атмосфер. Практическое применение пока невозможно.",
    "🌌 Пульсарное хронометрирование: массивы миллисекундных пульсаров могут обнаружить гравитационные волны наногерцового диапазона — от сливающихся сверхмассивных чёрных дыр.",
