    "🐑 Стадо бежит за хайпом, пастух стрижёт шерсть.",
    "💸 Leverage x100 — это не стратегия, это суицид с отложенным эффектом.",
    "🎭 Маркет-мейкер не враг, он просто зарабатывает на твоей глупости.",
    "🌪️ Волатильность — друг терпеливых и могила нетерпеливых.",
    "🦷 Рынок выбивает зубы тем, кто скалится без причины.",
    "🎯 Твоя точка входа — это чья-то точка выхода. Угадай, кто умнее.",
