    "🧪 Температура сэмплинга повышает стохастичность вывода: больше разнообразия — больше риска случайной правдоподобной ереси.",
    "📊 Метрики легко обмануть: оптимизируя то, что удобно считать, ты получаешь идеально посчитанное, но бесполезное.",
