    "🧪 «Сделай точно» — это не требование, а эмоция; требование начинается с допусков, форматов и тестов приемки.",
    "📐 С точки зрения информационной теории, модель — компрессор: она экономит биты, а потом расплачивается потерей тонких различий.",
    "🧠 Важная эвристика: если ответ не содержит условий применимости, он почти наверняка переобобщён.",
    "🔍 Out-of-distribution поведение — это момент, когда статистическая привычка притворяется экспертизой без лицензии.",
    "🧯 Без внешних источников модель может генерировать «ссылкоподобные» конструкции; правдоподобие ссылки не тождественно существованию источника.",
