    "💾 Человеческий мозг имеет емкость памяти, эквивалентную примерно 2.5 петабайтам (2.5 миллиона гигабайт). Этого хватит на 300 лет непрерывного видео.",
    "🧠 Научный факт: ИИ не «понимает» как человек — он подбирает следующий токен по статистическим закономерностям из данных и контекста.",
    "📚 Чем чище и разнообразнее данные обучения, тем меньше сюрпризов в ответах. Мусор на входе почти всегда даёт мусор на выходе.",
    "🧪 Тест на реальность: если модель уверенно спорит с учебником, чаще ошибается модель, а не физика.",
    "🔬 ИИ хорошо повторяет найденные паттерны, но плохо чувствует границы применимости. Поэтому «похоже» не равно «истинно».",
    "🧯 Галлюцинации — это не фантазия ради прикола, а побочный эффект генерации: модель может «додумать» правдоподобное без опоры на факты.",
    "🧭 Контекст решает: одна и та же модель может отвечать по-разному, если поменять формулировку, порядок фактов или добавить ограничения.",
    "🧱 Чем больше задач пытаешься запихнуть в один запрос, тем выше риск, что ИИ упустит важное. Декомпозиция — это не занудство, это инженерия.",
    "🧰 Хороший промпт — это не магия, а спецификация: цель, формат, ограничения, примеры и критерии «что считать правильным».",
    "🧫 ИИ наследует перекосы данных: если в обучающей выборке есть системные смещения, ответы будут отражать эти смещения, даже без злого умысла.",
    "🧷 Секрет прост: модель не знает, что ты «имел в виду». Она знает только то, что ты написал, и то, что статистически часто рядом встречалось.",
    "📏 Обобщение — это когда модель решает новую задачу, а не повторяет виденное. Поэтому важно проверять на данных, которых она не видела.",
    "🧯 Валидация нужна не только моделям, но и людям: если ответ кажется идеальным с первого раза, это повод перепроверить, а не праздновать.",
    "🕵️ Факт безопасности: если в текст попали пароли, сид-фразы или приватные ключи — это уже утечка, даже если ты «удалишь сообщение».",
    "🔐 Правило вежливой паранойи: ИИ можно давать структуру и требования, но нельзя давать секреты, которые нельзя потерять.",
    "🧮 Математика качества: точность ответа зависит не от уверенного тона, а от проверяемых ссылок, воспроизводимых шагов и ясных допущений.",
    "📎 ИИ любит конкретику: «сделай красиво» даёт случайный результат, а «сделай 3 варианта, 120–160 символов, без сленга» — управляемый.",
    "🧭 Инженерный факт: ограничения повышают качество. Запрети лишнее — и модель меньше расползётся в болтовню.",
    "🧲 Чем сильнее ты «подталкиваешь» ИИ к желаемому выводу, тем выше шанс получить убедительную ошибку. Это эффект ведущего вопроса.",
    "🧫 Факт про данные: даже маленькая утечка тестовых примеров в обучение может сделать метрики красивыми, а продукт — слабым.",
    "🧠 ИИ может быть креативным, но креативность не равна достоверности. Для фактов нужна проверка источниками или расчётами.",
    "🗂️ Лучший способ бороться с галлюцинациями — требовать: список предположений, шаги вывода и явное «не знаю», если данных нет.",
    "🧪 В науке ценится воспроизводимость: если ответ нельзя повторить и проверить, это не знание, а версия.",
    "🧭 Факт интерфейса: модель реагирует на роль и тон. «Ты строгий ревьюер кода» обычно даёт аккуратнее, чем «помоги пж».",
    "🔍 ИИ часто ошибается в редких случаях и краевых сценариях. Поэтому самые важные проверки — именно там, где «обычно всё работает».",
    "🧷 Факт про память: если система не хранит историю явно, модель «забывает» вне текущего контекста. Не рассчитывай на чудеса.",
    "🧰 Качество ответа растёт, когда ты даёшь входные данные: таблицы, логи, примеры, контрпримеры. Без данных будет гадание.",
    "🧱 Хороший формат спасает смысл: попроси JSON/таблицу/чек-лист — и вероятность полезного результата резко выше.",
    "📌 Ошибка формулировки — главная причина плохого ответа. ИИ не тупой, он буквально следует тому, что понял из текста.",
    "🧯 Факт эксплуатации: промпт-инъекции работают именно потому, что модель склонна следовать инструкциям из контента, если не фильтровать их.",
    "🧪 Чем больше свободы, тем больше вариативности. Для стабильности фиксируй требования и проси несколько вариантов с сравнением.",
    "🔁 Научный факт: обучение — это оптимизация функции потерь, а не загрузка «здравого смысла». Поэтому здравый смысл может давать сбои.",
    "🧠 ИИ не имеет внутреннего компаса «правды». Он имеет вероятности слов. Правду добавляет проверка: твоя или внешняя.",
    "📉 Метрики могут врать, если задача сформулирована криво. Можно оптимизировать «похоже на ответ» и потерять «полезно для пользователя».",
    "🧩 Разбиение задачи на подзадачи снижает ошибки: сначала собрать факты, потом построить план, потом написать итог.",
    "🧾 Факт документации: если требование не записано, оно будет нарушено. ИИ не угадывает корпоративные традиции.",
    "🧷 Если модель не задаёт уточнений, это не значит, что всё ясно. Часто это значит, что она выбрала «самую вероятную» трактовку.",
    "🧠 ИИ может объяснять уверенно даже неверное. Уверенность — это стиль генерации, а не показатель истинности.",
    "🧯 Факт про безопасность данных: всё, что ты вставляешь в запрос, потенциально может оказаться в логах системы. Думай как инженер, не как романтик.",
    "📦 Чем лучше описан вход, тем меньше «магии» в выходе. Магия — это просто недостающие требования.",
    "🧪 Научная привычка: проси модель перечислить ограничения своего ответа. Это отрезвляет и экономит время.",
    "🔍 Факт про проверку: самый быстрый способ поймать ошибку — попросить примеры, контрпримеры и граничные случаи.",
    "🧠 ИИ хорошо суммирует и структурирует, потому что это статистически частая задача в данных. Но «точные факты» требуют источников.",
    "🧰 Если нужен результат «как в проде», давай контекст «как в проде»: аудитория, тон, формат, запреты, примеры ошибок.",
    "📚 Факт про обучение людей: ИИ ускоряет работу, но не отменяет ответственность. Подпись под результатом всё равно твоя.",
    "🧭 Парадокс: чем умнее выглядит текст, тем проще поверить. Поэтому для важных вещей нужен второй контур — проверка и рецензия.",
