def get_random_phrase() -> str:
    """Возвращает случайную фразу Сенсея."""
    return random.choice(SENSEI_PHRASES)

def get_random_pour_phrase() -> str:
    """Возвращает случайную фразу для 'наливай'."""
    return random.choice(POUR_PHRASES)

def get_random_welcome(username: str) -> str:
    """Возвращает случайное приветствие."""
    return random.choice(WELCOME_PHRASES).format(username=username)

def get_random_ban_phrase(mention: str) -> str:
    """Возвращает случайную фразу бана."""
    return random.choice(BAN_PHRASES).format(name=mention)

def check_easter_egg(text: str) -> Optional[str]:
    """Проверяет текст на пасхалки (строго по словам)."""
    text_lower = text.lower()
    for pattern, value in EASTER_EGG_PATTERNS:
        if pattern.search(text_lower):
            return random.choice(value)
    return None
